"                        const { subtotal } = calculateTotals(activeCart);
                        const pointsRatio = business && business.points_to_amount_ratio !== undefined ? parseFloat(business.points_to_amount_ratio) : 1.00;
                        const maxRedeemable = Math.min(trayCustomer.points || 0, Math.floor(subtotal / pointsRatio));

                        return (
                          <div className={`flex items-center justify-between gap-2 px-2 py-1.5 rounded-lg border mt-1.5 ${
                            redeemedPoints > 0
                              ? (isDark ? 'bg-amber-500/5 border-amber-500/20' : 'bg-amber-50 border-amber-200')
                              : (isDark ? 'bg-slate-500/5 border-slate-700' : 'bg-slate-50 border-slate-200')
                          }`}>
                            <div className="flex items-center gap-1.5">
                              <Gift size={14} className={redeemedPoints > 0 ? 'text-amber-500' : 'text-[#10ac84]'} />
                              <span className={`text-[10px] font-black ${redeemedPoints > 0 ? 'text-amber-600' : 'text-slate-600 dark:text-gray-300'}`}>
                                {redeemedPoints > 0 
                                  ? `Redeemed: ${redeemedPoints} Pts (-${posSettings.currency || 'Rs'} ${(redeemedPoints * pointsRatio).toFixed(2)})`
                                  : `Loyalty Points: ${trayCustomer.points || 0} Pts`
                                }
                              </span>
                            </div>"

